def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'
    opp = [h[1] for h in history]
    my = [h[0] for h in history]
    opp_def = opp.count('D')
    if n == 99:
        return 'D'
    if opp_def == 0:
        if n < 20:
            return 'C'
        return 'D'
    if opp_def / n > 0.5:
        return 'D'
    last_opp = opp[-1]
    last_my = my[-1]
    if last_opp == 'C':
        return 'C'
    else:
        if opp_def == 1:
            return 'C'
        if last_my == 'D':
            if n >= 3 and opp[-2] == 'D' and opp[-3] == 'D':
                return 'C'
            return 'D'
        else:
            if opp_def / n > 0.3:
                return 'D'
            return 'C'
